// Arma las tres fuentes que escribe la maquina, como las dejan smoke-run.sh, el gate E2E por run-check y la firma del dev
// desde su terminal: AC 1 por el registro de pruebas de humo, AC 2 por el gate E2E (fila E1), AC 3 por la firma.
const fs = require('fs');
const path = require('path');
const S = process.env.SKILLS + '/skills/tycon-pipeline/scripts/lib/';
const w = require(S + 'runtime-waiver.js');
const estado = require(S + 'state-dir.js').stateDir(process.env.HOME);
fs.mkdirSync(estado, { recursive: true });
const gl = path.join(estado, 'gates.log');
const d = new Date(Date.now() - 60000);
const ts = d.toISOString().replace(/\.\d+Z$/, 'Z');
const dod = '.advisors/dod-runtime';
fs.mkdirSync(dod, { recursive: true });
// La linea del humo con el formato de la story 1.19 (v:2): la expectativa, la salida guardada y sus sellos en el espejo.
const sha = (x) => require('crypto').createHash('sha256').update(x).digest('hex');
const pasaSi = 'el listado responde 200 con el catalogo y su nombre';
const salida = 'HTTP/1.1 200\ncatalogo: Catalogo A\n';
const rel = '9.9-smoke-outputs/' + ts.replace(/[-:]/g, '') + '-a1b2c3.txt';
fs.mkdirSync(path.join(dod, '9.9-smoke-outputs'), { recursive: true });
fs.writeFileSync(path.join(dod, rel), salida);
fs.writeFileSync(path.join(dod, '9.9-smoke-ledger.jsonl'), JSON.stringify({ ts, story: '9.9', acs: [1], cmd: 'curl -s http://app/catalogos', exit: 0, via: 'smoke-run.sh', v: 2, pass_if: pasaSi, output: rel, output_sha: sha(salida) }) + '\n');
fs.appendFileSync(gl, JSON.stringify({ type: 'smoke-run', ts, story: '9.9', acs: [1], exit: 0, v: 2, pass_if_sha: sha(pasaSi), output_sha: sha(salida) }) + '\n');
fs.writeFileSync(path.join(dod, '9.9-e2e-gate-' + ts.replace(/[-:]/g, '') + '.md'), '# DoD Runtime Evidence — Story 9.9 — Playwright Gate (scoped)\n**Spec filter**: story-9-9.spec.ts\n```\nverdict=PASS\n```\n- skipped: 0\n');
fs.appendFileSync(gl, JSON.stringify({ ts: new Date().toISOString(), check: 'dod', status: 'green', provenance: 'run-check', cmd: 'bash e2e-gate.sh /fe 9.9 /dir story-9-9.spec.ts', exit: 0 }) + '\n');
fs.writeFileSync('.advisors/tests-result.json', JSON.stringify({ ts: new Date().toISOString(), story_id: '9.9', suite_green: true }));
w.appendWaiver({ story: '9.9', acs: [3], matrixHash: 'x', approvedBy: 'deva', nowIso: new Date().toISOString(),
  declHashByAc: { 3: w.declHashFor('el envio real lo hace un servicio externo', 'T3') }, logPath: '.tycon/runtime-waivers.jsonl' });
if (process.argv[2] === 'sin-firma') fs.writeFileSync('.tycon/runtime-waivers.jsonl', '');

